arguments.variable_payload:
{% set model_details = vars.input.params.fmg_payload%}
{% set variable_payloads = [] %}
{%for key, value in model_details.device["meta variables"].items() %}
{% do variable_payloads.append(
{ "connector_config": vars.input.params.connector_config,
  "adom": model_details.adom,
  "variable": key,
   "value": value,
   "description": "Created by FortiSOAR",
 "device": model_details.device.name,
}
)%}
{% endfor %}
{{variable_payloads}}

arguments.device_status:
{# this is the latest info retrieved directly from the gates #} 
{% set latest_fgt_devices_info = vars.steps.Get_Each_Fortigate_Status | json_query('[].output')%}

{# contains info like fgt_ip/hostname, fmg adom, desired groups, etc #}
{% set desired_fgt_devices_state = vars.input.params['device_list'] %}


{# merge the two device dicts by device_ip #}
{% set merged_devices = [] %}
{% for latest in latest_fgt_devices_info %}
    {% for desired in desired_fgt_devices_state %}
        {% if latest.fgt_ip == desired.fgt_ip %}
            {% set merged_device = latest.copy() %}
            {% for key, value in desired.items() %}
                {% do merged_device.update({key: value}) %}
            {% endfor %}
            {% do merged_devices.append(merged_device) %}
            {% break %}
        {% endif %}
    {% endfor %}
{% endfor %}

{{ merged_devices }}

arguments.model_device_payloads:
{% set new_up_device_names = vars.up_devices | json_query('[].name') %}
{% set model_list = [] %}
{% for device in vars.device_status %}
   {# Only create a model device config if the device is not up #}
   {% if device.fgt_name not in new_up_device_names %}
        {% do model_list.append({
          "adom": device.fmg_adom,
          "device": {
              "adm_usr": device.fgt_user,
              "adm_pass": device.fgt_pass,
              "device action": "add_model",
              "mgmt_mode": "fmg",
              "mr": device.fgt_version.split('.') | json_query('[1]') | int ,
              "name": device.fgt_name,
              "os_type": "fos",
              "os_ver": "7.0",
              "platform_str": "FortiGate-VM64-KVM",
              "sn": device.fgt_serial, 
              "meta variables": {
                   "branch_id": device.fgt_name | regex_search('\d+') | default("", true)
              }
          },
          "groups": [{"name": device.fmg_device_group}],
          "flags": [ "create_task"],
		}) %}
  {% endif %}
{% endfor %}
{{ model_list }}

